python3 -c "
import zipfile, xml.etree.ElementTree as ET

with zipfile.ZipFile('/root/renewal_playbook_updated.hwpx', 'r') as z:
    for name in ['Contents/section0.xml', 'Contents/section1.xml']:
        print(f'=== {name} ===')
        content = z.read(name).decode('utf-8')

        # Check old values are gone
        old_vals = ['Northwind', '이전담당자', '2025-04-01', '2025-04-15', 'Standard-18M', 'ops-old@northwind.example', '기존 메모를 새 메모로 바꾸세요.', 'old follow-up alpha', 'old follow-up beta', 'old follow-up gamma']
        for v in old_vals:
            if v in content:
                print(f'  FAIL: old value still present: {v}')
            else:
                print(f'  OK: old value gone: {v}')

        # Check new values present
        new_vals = ['Asteron Commerce', '한예진', '2026-08-12', '2026-08-26', 'Priority-24M', 'renewals-escalation@asteron.example', '가격 검토가 끝날 때까지 할인 문구를 왔부에 공유하지 마세요.']
        for v in new_vals:
            if v in content:
                print(f'  OK: new value present: {v}')
            else:
                print(f'  FAIL: new value missing: {v}')

        # Check appendix
        if '이 부록 문단은 그대로 유지해야 합니다.' in content:
            print('  OK: appendix preserved')
        else:
            print('  FAIL: appendix missing')

        # Check linesegarray
        root = ET.fromstring(content)
        ns = {'hp': 'http://www.hancom.co.kr/hwpml/2010/HWPML'}
        for para in root.findall('.//hp:p', ns):
            para_text = ''.join(t.text or '' for t in para.findall('.//hp:t', ns))
            has_lineseg = para.find('hp:linesegarray', ns) is not None
            if has_lineseg:
                print(f'  linesegarray present in para: {para_text[:50]}')
            else:
                print(f'  NO linesegarray in para: {para_text[:50]}')
"

